WITH with_last AS (SELECT s.*, latest.category FROM suppliers s LEFT JOIN LATERAL (SELECT c.category FROM products c WHERE c.supplier_id = s.id ORDER BY c.launch_date DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT CASE WHEN rating >= 4.2 THEN 'HIGH' ELSE 'LOW' END AS rating_tier, SUM(rating) AS total_rating, APPROX_PERCENTILE(rating, ARRAY(0.25, 0.5, 0.75)) AS rating_quartiles FROM with_last GROUP BY CASE WHEN rating >= 4.2 THEN 'HIGH' ELSE 'LOW' END HAVING total_rating < 0
